import sys; sys.path.insert(0,'/home/claude/scripts')
from facts_lib import save
N="تعليمات برنامج درجة الماجستير في الطب البيطري السريري"
F=[]
def r(c,a,q1,q2,q3): F.append(("rule",[1],c,a,q1,q2,q3))
r("المادة 1 و2","تسري تعليمات برنامج الماجستير في الطب البيطري السريري على الطلبة المقبولين اعتباراً من العام الدراسي 2020/2021. والسنة الدراسية أحد عشر شهراً مقسمة على ثلاثة فصول دراسية إجبارية مدة كل منها ستة عشر أسبوعاً تشمل الامتحانات والأبحاث والنشاطات الأخرى، وتحدد من لجنة الكلية بتنسيب من الأقسام المعنية.","على من تسري تعليمات الماجستير في الطب البيطري السريري ومن أي عام؟","كم فصلاً وكم أسبوعاً تتكون السنة الدراسية في ماجستير الطب البيطري السريري؟","متى بلشت تنطبق تعليمات الماجستير البيطري السريري؟")
r("المادة 3 و4","متطلبات برنامج الماجستير في الطب البيطري السريري 45 ساعة معتمدة حسب الخطة التي يقرها مجلس العمداء، وفي مسار الامتحان الشامل 45 ساعة مساقات والامتحان الشامل بصفر ساعة معتمدة. وتوزع الساعات لمساري الرسالة والشامل: 36 ساعة مساقات إجبارية من مستوى 700، و9 ساعات اختيارية من مستوى 700، ومساق ط ب 798 للامتحان الشامل (مسار الشامل).","كم ساعة معتمدة متطلبات الماجستير في الطب البيطري السريري وكيف توزع؟","ما رمز مساق الامتحان الشامل في ماجستير الطب البيطري السريري؟","كم ساعة إجباري وكم اختياري بالماجستير البيطري؟")
r("المادة 5 و7","تقدم طلبات الالتحاق ببرنامج الدراسات العليا إلكترونياً ولا يبت في أي طلب إلا إذا استوفى جميع الأوراق الثبوتية، وتحول إلى الكلية والأقسام للنظر والتنسيب بأسماء المرشحين حسب الشواغر إلى عمادة كلية الدراسات العليا لإعلان القوائم. ويتم قبول الطالب بقرار من العميد بناءً على توصية لجنة القسم وتنسيب لجنة الكلية، ويبلغ القرار للطالب والمسجل العام والكلية.","كيف تقدم طلبات الالتحاق بماجستير الطب البيطري السريري ومن يقرر القبول؟","هل يبت في الطلب إذا لم تستوف الأوراق الثبوتية؟","مين بقرر قبولي بالماجستير البيطري؟")
r("المادة 6 (أ، ب)","الحاصل على البكالوريوس بتقدير مقبول يحق له الالتحاق بشرط دراسة 3 مواد من مواد الماجستير خلال السنة الأولى يحددها القسم وتكون موحدة لجميع المتقدمين، والنجاح في كل مادة بعلامة لا تقل عن C+ وبمعدل تراكمي لا يقل عن 3.00 ليصبح طالباً نظامياً وإلا يعد قبوله لاغياً ويفصل. ويحصر قبول الحاصلين على مقبول بنسبة 25% من المستجدين فعلياً في كل فصل: 10% حداً أعلى للأردنيين و15% حداً أدنى للوافدين.","ما شروط قبول حامل البكالوريوس بتقدير مقبول في ماجستير الطب البيطري السريري؟","ما نسبة قبول الحاصلين على مقبول من الأردنيين والوافدين؟","تقديري مقبول بالبكالوريوس، بقدر أقدم على الماجستير البيطري؟")
r("المادة 6 (ج-ط)","يشترط أيضاً: أن تكون دراسة البكالوريوس في الطب والجراحة البيطرية بالانتظام، وألا يكون قد صدرت بحقه عقوبة تأديبية تمنع قبوله في الدراسات العليا، وأن يحقق الشروط التي تقترحها لجنة القسم وتقرها لجنة الكلية، وألا يكون فصل من التخصص، واجتياز امتحان اللغة حسب قرارات وزارة التعليم العالي. وللقسم أن يحدد عند القبول مساقات استدراكية من مستوى البكالوريوس بما لا يزيد عن 9 ساعات لا تدخل في المعدل التراكمي ولا في متطلبات التخرج ولا في الحد الأعلى لمدة الدراسة.","هل يقبل خريج البكالوريوس بالانتساب في ماجستير الطب البيطري السريري؟","كم ساعة استدراكية كحد أعلى يحددها القسم عند القبول؟","هل تدخل المساقات الاستدراكية بالمعدل التراكمي في الماجستير البيطري؟")
r("المادة 8","يجوز تمديد مدة الدراسة في الماجستير فصلين دراسيين بقرار من العميد بناءً على توصية لجنة القسم وتنسيب لجنة الكلية، على أن يتم ذلك قبل نهاية الفصل الذي يسبق فصل التمديد، ويبلغ القرار للطالب والمسجل العام والكلية.","من يقرر تمديد مدة الدراسة في ماجستير الطب البيطري السريري ومتى يطلب؟","كم فصلاً يمدد وبأي إجراء؟","كيف بمدد مدة دراستي بالماجستير البيطري؟")
r("المادة 9 (أ، ب، د)","على الطالب الراغب بالتأجيل التقدم بطلب للعميد قبل بداية فترة الامتحانات النهائية لذلك الفصل، ويقبل بقرار من العميد بناءً على توصية لجنة القسم وتنسيب لجنة الكلية. ولا تحتسب مدة التأجيل من الحد الأعلى لمدة الدراسة ولا لغاية إزالة أسباب الوضع تحت المراقبة. ولا يجوز لمن عنده غير مكتمل تأجيل دراسته إلا بعد إزالة الملاحظة وإلا ترصد له علامة الأعمال الفصلية.","متى يقدم طلب تأجيل الدراسة في ماجستير الطب البيطري السريري؟","هل تحتسب مدة التأجيل من الحد الأعلى للدراسة؟","ممكن أأجل وعندي غير مكتمل؟")
r("المادة 10","يعتبر الطالب فاقداً لمقعده إذا انقطع فصلاً دراسياً واحداً دون عذر يقبله العميد (يقدم العذر قبل بداية الفصل الذي يلي فصل الانقطاع وتحسب مدة الانقطاع من الحد الأعلى)، أو ألغي تسجيله لعدم دفع الرسوم، أو لم يسجل للفصول في الأوقات المحددة. وللراغب بالانسحاب من الجامعة التقدم بطلب إلكتروني فتثبت ملاحظة «منسحب من الجامعة» ويفقد مقعده.","متى يعتبر طالب الماجستير البيطري السريري فاقداً لمقعده؟","كيف ينسحب الطالب من الجامعة وما أثره؟","شو بخلي مقعدي يطير بالماجستير البيطري؟")
r("المادة 10 (ج)","يجوز للطالب الذي فقد مقعده التقدم بطلب جديد للقبول في نفس تخصصه، فإذا قبل وكانت الخطة التي درس عليها سابقاً فعالة يحتفظ بسجله الأكاديمي كاملاً وتحسب مدة دراسته السابقة ضمن الحدين الأعلى والأدنى. وإذا كانت الخطة المعمول بها مختلفة تطبق عليه الفقرة (ب) من المادة 11.","ماذا يحدث لسجل الطالب الفاقد لمقعده إذا أعيد قبوله في نفس التخصص؟","هل تحسب مدة دراسته السابقة بعد إعادة القبول؟","فقدت مقعدي وبدي أرجع، علاماتي بتضل؟")
r("المادة 11 (أ، ب)","إذا قبل الطالب قبولاً جديداً في تخصصه بعد فقدان المقعد أو انتقل من ماجستير إلى ماجستير آخر، يجوز للقسم المقبول فيه أن يحسب أو يعادل له ما لا يزيد عن 12 ساعة معتمدة بما يناظرها من مساقات الماجستير ويعفيه منها، وتدخل في معدله التراكمي بشرط ألا تقل علامة أي منها عن C+، ويحسم من الحد الأعلى لمدة الدراسة فصل دراسي مقابل كل 9 ساعات محتسبة.","كم ساعة تعادل عند الانتقال من برنامج ماجستير آخر أو إعادة القبول؟","كيف يحسم من مدة الدراسة مقابل الساعات المعادلة؟","انتقلت من ماجستير ثاني، كم ساعة بتنحسب لي؟")
r("المادة 11 (ج، د)","إذا انتقل الطالب من تخصص دقيق إلى آخر ضمن البرنامج يجوز للقسم أن يعادل له بعض مساقات التدريب العملي أو السريري على ألا تتجاوز الساعات المعادلة 18 ساعة وألا تقل علامته في كل منها عن C+، وتحسب في المعدل التراكمي ويحسم من الحد الأعلى فصل مقابل 9 ساعات. ويجوز الانتقال من مسار الرسالة إلى مسار الامتحان الشامل وبالعكس بتوصية مجلس القسم وتنسيب لجنة الكلية وموافقة المجلس.","كم ساعة تدريب عملي أو سريري تعادل عند الانتقال بين التخصصات الدقيقة؟","هل يجوز الانتقال من مسار الرسالة إلى الامتحان الشامل؟","بدي أحول من رسالة لشامل، كيف؟")
r("المادة 11 (هـ، ز)","يجوز للطالب المنتقل من ماجستير في جامعة أخرى أن يعادل له القسم ويعفيه من مساقات لا تتجاوز 9 ساعات معتمدة وبعلامة لا تقل عن B+ أو 70 فما فوق، ولا تدخل علاماتها في المعدل التراكمي ويحسم من الحد الأعلى فصل مقابل 9 ساعات. ويتقدم الطالب بطلب احتساب المساقات للقسم خلال الشهر الأول بعد قبوله وفي جميع الحالات تكون المعادلة خلال الفصل الأول لالتحاقه.","كم ساعة تعادل لمن ينتقل من ماجستير جامعة أخرى وما العلامة المطلوبة؟","خلال كم من الوقت يقدم طلب احتساب المساقات بعد القبول؟","انتقلت من جامعة ثانية، متى بقدم طلب المعادلة؟")
r("المادة 12","يسمح للطالب بدراسة مساق عملي (سريري) واحد لفصل دراسي واحد فقط في مؤسسات تعليمية أو تدريبية خارج الجامعة (يستثنى اتفاقيات التبادل الطلابي) بموافقة العميد بتنسيب لجنة الكلية وتوصية لجنة القسم، ويعفى منه بشرط ألا تقل علامته عن B- ولا تدخل علامته في المعدل، وبألا يتجاوز مجموع هذه الساعات والساعات المحتسبة من انتقاله من جامعة أخرى 12 ساعة معتمدة.","هل يسمح لطالب الماجستير البيطري السريري بدراسة مساق سريري خارج الجامعة؟","ما الحد الأدنى للعلامة وأقصى ساعات للمساق الخارجي؟","بقدر أدرس مساق سريري بمستشفى برا الجامعة؟")
r("المادة 13 (ب-د)","يسمح للطالب بالانسحاب من مساق قبل بداية فترة الامتحانات النهائية فيثبت المساق في السجل بملاحظة «منسحب» ولا يدخل في ساعات النجاح والرسوب أو متطلبات التخرج، ولا يجوز الانسحاب من جميع المساقات إلا بعذر قهري يقبله العميد، وتعتبر دراسته للفصل مؤجلة ويحسب من مدة التأجيل المسموح بها، وإذا كان في الفصل الأول من دراسته يعتبر منسحباً من الجامعة. وتلغى المنحة التشغيلية في ذلك الفصل ويوقف صرف المستحقات.","متى يسمح بالانسحاب من مساق وماذا يثبت في السجل؟","ماذا يحدث للمنحة التشغيلية إذا انسحب الطالب من جميع المساقات؟","انسحبت من كل المواد بالفصل الأول، شو بصير؟")
r("المادة 14 (أ، ب)","يدخل مدرس المساق الغياب على نظام الغياب الإلكتروني بشكل دوري خلال عشرة أيام من موعد الغياب ويمنع إدخال غياب لأي طالب مضى على محاضرته أكثر من عشرة أيام. وإذا غاب أكثر من 20% يحرم من الامتحانات اللاحقة ويجوز له إسقاط المساق إلكترونياً خلال فترة الإسقاط، وإلا يوضع له الرمز (C) «محروم بسبب الغياب» وتدخل نقاطه في المعدل التراكمي، ولعميد الكلية تجاوز 20% بعذر قهري.","ما الرمز الذي يوضع للطالب المحروم بسبب الغياب في الماجستير البيطري السريري؟","خلال كم يوماً يدخل المدرس الغياب على النظام؟","غبت أكثر من 20% بمساق، شو بصير فيه؟")
r("المادة 14 (ج، د)","في الحالات التي يتجاوز فيها غياب الطالب 20% أو ما يعادله حسب طبيعة التخصص يجوز له الانسحاب من جميع المساقات، وفي حال موافقة المجلس يعتبر منسحباً وتعتبر دراسته مؤجلة لذلك الفصل ولا ترصد الرسوم المدفوعة، ويبلغ إلكترونياً قبل موعد الامتحانات النهائية، وخلاف ذلك يوضع له الرمز (F) «محروم بسبب الغياب» لكافة المساقات وتدخل في معدله. ومدرس المساق ورئيس القسم وعمداء الكلية مسؤولون عن تنفيذ المواظبة.","ماذا يحدث إذا تجاوز غياب الطالب 20% في كافة المساقات ولم ينسحب؟","هل ترصد الرسوم المدفوعة عند الانسحاب بسبب الغياب؟","من المسؤول عن تنفيذ أحكام المواظبة؟")
r("المادة 15 (أ، ب) جدول الرموز","تترك صلاحية ربط علامات الطلبة بالرموز لعضو هيئة التدريس/منسق المساق، والنقاط: C = 2.0، C+ = 2.3، B- = 2.7، B = 3.0، B+ = 3.3، A- = 3.7، A = 4.0، A+ = 4.3.","كم نقطة يقابل كل رمز (C إلى A+) في ماجستير الطب البيطري السريري؟","كم نقاط الرمز B+ والرمز A-؟","كم نقطة الـ B بالماجستير؟")
r("المادة 15 (هـ، و)","يعلن مدرس المساق نتائج مجموع الأعمال الفصلية قبل بدء الامتحانات النهائية بأسبوع على الأقل ويسلم نسخة لرئيس القسم. والعلامة النهائية لكل مساق هي مجموع علامات الامتحان النهائي والأعمال الفصلية، وقد تكون بعضها أعمالاً تطبيقية أو تقارير أو بحوثاً، ويحدد مجلس القسم كيفية الامتحانات وتوزيع العلامات في بداية كل فصل.","قبل كم يعلن المدرس نتائج الأعمال الفصلية في الماجستير البيطري السريري؟","من يحدد كيفية الامتحانات وتوزيع العلامات؟","متى بتنزل علامات الأعمال الفصلية؟")
r("المادة 15 (ز، ح)","إذا لم يتم الطالب متطلبات مساق أو تغيب عن الامتحان النهائي بعذر مرضي أو قهري يقبله العميد تسجل له «غير مكتمل»، وعليه إزالتها خلال أسبوعين من بدء الفصل اللاحق وإلا ترصد له علامة الأعمال الفصلية. وفي حالة قبول العذر يعقد امتحان تعويضي بالتنسيق خطياً مع رئيس القسم مكافئاً للامتحان الذي غاب عنه بنوع الأسئلة ومستواها.","خلال كم أسبوعاً يجب إزالة ملاحظة «غير مكتمل» في الماجستير البيطري السريري؟","كيف يكون الامتحان التعويضي لمن غاب بعذر مقبول؟","غبت عن النهائي بعذر، شو بصير بعلامتي؟")
r("المادة 16 (أ-د)","الحد الأدنى لرمز النجاح في المساق C+، والحد الأدنى لرمز نتيجة المساق C. والمعدل التراكمي هو معدل نقاط رموز جميع المساقات التي درسها الطالب نجاحاً أو رسوباً ضمن الخطة المعتمدة، وإذا حصل على «غير مكتمل» يحسب معدله عند اكتمال العلامات وتعتبر المعدلات ذات أثر رجعي من حيث المراقبة أو الفصل. والمعدل الفصلي هو معدل نقاط رموز مساقات ذلك الفصل، ويحسب كلاهما لأقرب منزلتين عشريتين.","ما الحد الأدنى لرمز النجاح في المساق في الماجستير البيطري السريري؟","كيف يحسب المعدل التراكمي والفصلي وإلى كم منزلة عشرية؟","شو أقل رمز نجاح بالماجستير البيطري؟")
r("المادة 17 (أ-3، ب-د)","يوضع الطالب تحت المراقبة أيضاً إذا أفاد تقرير مشرف البرنامج السنوي بعدم التزامه بمهامه أو بإهماله العمل على الرسالة. وعلى الموضوع تحت المراقبة إزالتها خلال ثلاثة فصول بعد الفصل الذي وضع فيه، وفي حالة البند (3) ترجع الإزالة للمشرف بالكتابة لرئيس القسم وعميد الكلية. ولا يجوز التسجيل لمساق الرسالة لمن وضع تحت المراقبة بسبب البندين (1، 2)، ولا التقدم للامتحان الشامل.","هل يسجل الطالب الموضوع تحت المراقبة لمساق الرسالة أو يتقدم للامتحان الشامل؟","من يزيل الوضع تحت المراقبة بسبب إهمال الرسالة؟","وضعوني تحت المراقبة، شو ما بقدر أعمل؟")
r("المادة 18","لا يجوز للطالب إعادة دراسة أي مساق حصل فيه على علامة (3.00) أو أكثر، ولا يجوز إعادة دراسة المساق الواحد أكثر من مرة واحدة، وتحسب العلامة الأعلى في المعدل التراكمي ولأغراض التخرج.","هل يجوز إعادة مساق حصل فيه الطالب على 3.00 أو أكثر؟","كم مرة يسمح بإعادة المساق وأي علامة تحسب؟","بقدر أعيد مادة نجحت فيها بـ B؟")
r("المادة 19 (أ)","يفصل الطالب من برنامج الماجستير إذا: رسب في مساقين إجباريين مختلفين في فصل واحد ونقص معدله عن 3.00؛ أو رسب في مساق إجباري مرتين ونقص معدله عن 3.00؛ أو رسب في مساق إجباري ثلاث مرات؛ أو لم يتمكن من إزالة الوضع تحت المراقبة؛ أو قرر المجلس أو لجنة المناقشة رسوبه؛ أو لم يتم المتطلبات ضمن الحد الأعلى؛ أو انطبقت عليه المادة 6 (أ) ولم يحقق شروط التحول إلى نظامي؛ أو رسب في الامتحان الشامل مرتين.","ما حالات الفصل من برنامج ماجستير الطب البيطري السريري؟","هل يفصل من رسب في مساق إجباري ثلاث مرات؟","شو بخليني أنفصل من الماجستير البيطري؟")
r("المادة 19 (ج) و20 و21","تصدر جميع قرارات الفصل من مجلس العمداء بناءً على تنسيب المجلس. والامتحان الشامل ذو طبيعة شاملة تكاملية يهدف إلى قياس قدرة الطالب على الربط بين المفاهيم الأساسية والمتقدمة وتوظيفها في حل المشكلات العلمية والتطبيقية في مجال تخصصه، وتعده لجنة القسم وتدير شؤونه.","ما هدف الامتحان الشامل في الماجستير البيطري السريري ومن يعده؟","من يصدر قرارات الفصل؟","شو الامتحان الشامل ومين بحضره؟")
r("المادة 22 و23","يتقدم الطالب للامتحان الشامل بعد إنهائه جميع المساقات المقررة بمعدل تراكمي لا يقل عن 3.00 فيها. ويسمح بالتقدم له مرتين فقط، وفي حال رسوبه الثانية يفصل ويمنح الدبلوم العالي حسب المادة 19 (ب)، ورمز النجاح فيه B، وتسجل النتيجة في كشف العلامات بعبارة (ناجح) أو (راسب).","متى يتقدم الطالب للامتحان الشامل وكم مرة؟","ماذا يحدث إذا رسب في الامتحان الشامل مرتين؟","كيف بتسجل نتيجة الشامل بالكشف؟")
r("المادة 24 (1-3، 5-9)","من متطلبات منح الدرجة: النجاح في جميع المساقات قبل المناقشة، ومعدل تراكمي لا يقل عن 3.00، وقضاء الحد الأدنى للمدة وعدم تجاوز الحد الأعلى، وإعداد الرسالة والنجاح في مناقشتها وتسليمها أو النجاح في الامتحان الشامل حسب المسار، وتسليم القسم وكلية الدراسات العليا ومكتبة الجامعة نسخة إلكترونية معتمدة ونسخة ورقية للمكتبة، وتقديم تفويض خطي للجامعة بنشر محتوى الرسالة وتعود الملكية الفكرية للجامعة. وتمنح شهادات التخرج عند استحقاقها في كل فصل.","ما الذي يجب تسليمه بعد مناقشة الرسالة في الماجستير البيطري السريري؟","لمن تعود حقوق الملكية الفكرية للرسالة؟","شو لازم أسلم عشان أتخرج؟")
r("المادة 24 (8، 10)","يشترط لتخرج طالب مسار الرسالة إثبات إرسال ورقة بحثية أعدها من بحثه مع مشرفه إلى مجلة عالمية متخصصة مفهرسة في Scopus أو مؤتمر عالمي متخصص مدرج في Scopus أو مجلات محلية معتمدة لأغراض الترقية في الجامعة. ويصنف التقدير بالمعدل التراكمي: جيد جداً 3.00–3.49، ممتاز 3.50–3.99، متميز 4.00–4.30.","ما شرط النشر لتخرج طالب مسار الرسالة؟","كيف يصنف تقدير الماجستير حسب المعدل التراكمي؟","كم المعدل اللي بخليني متميز؟")
r("المادة 25","تقدم الرسالة مطبوعة حسب أسلوب كلية الدراسات العليا: صفحة العنوان الأولى تحتوي عنوان الرسالة واسم الطالب واسم المشرف والمشرف المشارك والعبارة «قدمت هذه الرسالة استكمالاً لمتطلبات الحصول على درجة الماجستير في الطب البيطري السريري من كلية الدراسات العليا في جامعة العلوم والتكنولوجيا الأردنية» وتاريخ التقديم، والصفحة الثانية أسماء لجنة المناقشة وتواقيعهم، والثالثة قائمة الأوراق البحثية الناتجة عن الرسالة.","ماذا تحتوي صفحات العنوان الثلاث في رسالة الماجستير البيطري السريري؟","ما العبارة التي تكتب على صفحة العنوان الأولى؟","شو بنكتب على غلاف الرسالة؟")
r("المادة 26 و27 (أ، ب)","يقوم رئيس القسم بإرشاد الطلبة طيلة دراستهم وله أن يعين من يساعده في الإرشاد. ويعين مشرف الرسالة من أعضاء هيئة التدريس برتبة أستاذ مشارك على الأقل بقرار المجلس قبل نهاية الفصل الثالث لالتحاق الطالب، بشرط استمرار إنتاجه العلمي بعد آخر ترقية بعامين، ويجوز لأستاذ مساعد لديه بحثان منشوران أو مقبولان في آخر ثلاث سنوات. ويكون المشرف الرئيسي من داخل الجامعة ومتفرغاً تفرغاً تاماً.","من يشرف على رسالة الماجستير في الطب البيطري السريري وبأي رتبة ومتى يعين؟","هل يجوز لأستاذ مساعد الإشراف على الرسالة؟","متى بنعين لي مشرف؟")
r("المادة 27 (ج، د)","يجوز تغيير المشرف لظروف خاصة تقبلها لجنة الكلية، ويجوز تسمية مشرف مشارك رتبته أستاذ مساعد على الأقل. ويحسب للمشرف ساعة تدريسية لكل طالب في كل فصل لمدة أربعة فصول متتالية كحد أعلى (ويقسم مع المشرف المشارك). ونصاب المشرف المنفرد: الأستاذ 5 طلاب، والأستاذ المشارك 4، والأستاذ المساعد 3، ويمكن مضاعفة العدد مع المشرف المشارك، ويجوز زيادته في حالات اضطرارية يقررها المجلس.","كم طالباً يحق لكل رتبة الإشراف عليهم؟","كم ساعة عبء تدريسي تحسب للمشرف على كل طالب؟","كم مدة احتساب عبء الإشراف؟")
r("المادة 27 (هـ)","يجوز بقرار المجلس أن يستمر عضو هيئة التدريس الحاصل على إجازة تفرغ علمي أو بدون راتب أو إعارة أو انتداب داخل الأردن في الإشراف، وأن يشارك في الإشراف من سبق له شغل رتبة أستاذ مساعد على الأقل في جامعة معترف بها ومقيم في الأردن بأقدمية سنتين، أو من غير العاملين في الجامعات إذا كان حاصلاً على الدكتوراه وخبرة عملية لا تقل عن 3 سنوات. وإذا كان خارج الأردن يستمر كمشرف مشارك في حالات اضطرارية.","من يجوز له المشاركة في الإشراف من خارج الجامعة؟","هل يستمر المشرف في الإشراف أثناء الإجازة أو الإعارة؟","ممكن دكتور من برا الجامعة يشارك بالإشراف؟")
r("المادة 28","يتوصل الطالب بتوجيه مشرفه إلى موضوع رسالته وخطتها وتقدم إلى لجنة القسم للتوصية بشأنها إلى لجنة الكلية في موعد لا يتجاوز نهاية الفصل الرابع لالتحاقه، ويقر المجلس الموضوع والخطة ويعلم عميد الكلية وعميد البحث العلمي والمسجل العام. ويشترط إقرارهما قبل تقديم مشروع البحث إلى عمادة البحث العلمي، ويجوز تغيير الموضوع أو الخطة أو العنوان بنفس طريقة الإقرار.","متى يقدم الطالب موضوع رسالته وخطتها ومن يقرها؟","هل يجوز تغيير موضوع الرسالة أو عنوانها؟","آخر موعد لتقديم خطة الرسالة؟")
r("المادة 29","يعين المجلس لجنة مناقشة الرسالة من المشرف رئيساً والمشرف المشارك (إن وجد) وعضوين آخرين على الأقل من حملة الدكتوراه أو ذوي الخبرة من حملة الماجستير، على ألا يقل عدد الأكاديميين عن نصف الأعضاء ويجب أن يكون أحدهم من خارج الجامعة. وتتم التوصية بتشكيلها قبل ستة أسابيع على الأقل من موعد المناقشة، ويجوز استثناء المشرف المشارك من خارج الأردن في حالات اضطرارية.","كيف تتشكل لجنة مناقشة رسالة الماجستير وقبل كم أسبوع من المناقشة؟","هل يشترط عضو من خارج الجامعة في لجنة المناقشة؟","كم عضو بلجنة المناقشة؟")
r("المادة 30","يقدم الطالب نسخة من رسالته لكل عضو من لجنة المناقشة قبل ثلاثة أسابيع على الأقل مع نموذج التقييم. ويحدد العميد موعد المناقشة بعد إنهاء الطالب جميع المتطلبات الأخرى بتنسيب لجنة الكلية قبل أسبوع على الأقل مرفقاً بتوصيات الأعضاء بجاهزية الرسالة. ولا يتقدم للمناقشة إلا بعد إتمام خطته بنجاح بمعدل لا يقل عن 3.00، ويلتزم الجميع بالأرواب الجامعية وتصور الكلية المناقشة.","قبل كم أسبوع يسلم الطالب الرسالة لأعضاء لجنة المناقشة؟","متى يحق للطالب التقدم لامتحان مناقشة الرسالة؟","هل لازم ألبس روب بالمناقشة؟")
r("المادة 31 (أ، ب)","قرار لجنة المناقشة بإحدى الصيغ: (ناجح) بدون تعديلات أو بتعديلات طفيفة مع تسليم الرسالة خلال 4 أسابيع من المناقشة؛ (ناجح) بتعديلات أساسية مع التسليم خلال 8 أسابيع وتنسيق أسبوعي مع المشرف؛ تأجيل القرار لتعديلات جوهرية مع إعادة المناقشة دون تجاوز الحد الأعلى لمدة الدراسة (والقرار بعدها ناجح أو راسب)؛ أو (راسب) وتطبق عليه المادة 19 (أ-5).","ما الصيغ التي يصدر بها قرار لجنة مناقشة الرسالة ومدد التسليم لكل منها؟","كم أسبوعاً لتسليم الرسالة بعد المناقشة بتعديلات أساسية؟","نجحت بتعديلات طفيفة، كم أسبوع بدي أسلم؟")
r("المادة 31 (ج-هـ)","يرفع المشرف القرار موقعاً من أعضاء اللجنة إلى رئيس القسم الذي يبلغه إلكترونياً للعميد وعميد الكلية والمسجل العام، ولا يثبت نجاح الطالب في المناقشة في سجله إلا بعد تسليم الرسالة في الفترة المحددة. وللمجلس تمديد فترة التسليم مدة لا تزيد عن 4 أسابيع لمرة واحدة بطلب الطالب وموافقة المشرف، وإلا يعدل قرار المناقشة إلى (راسب) وتطبق المادة 19 (أ-5).","متى يثبت قرار نجاح الطالب بالمناقشة في سجله؟","ماذا يحدث لمن لم يسلم الرسالة في المدة المحددة؟","كم أمدد فترة تسليم الرسالة؟")
r("المادة 32 إلى 34","تتولى لجنة الدراسات العليا في الكلية التنسيق بين الأقسام فيما يتعلق بالبرنامج وتخصصاته، والتنسيب للمجلس بإقرار موضوع وخطة الرسالة، وأية أمور يفوضها بها المجلس. ويمنح الطالب بعد إنهاء جميع المساقات السريرية والأكاديمية شهادة اختصاص Master in Veterinary Clinical Sciences، ويبت مجلس العمداء في الإشكاليات الناشئة عن التطبيق.","ما الشهادة التي تمنح بعد إنهاء متطلبات ماجستير الطب البيطري السريري؟","من يبت في الإشكاليات الناشئة عن تطبيق تعليمات البرنامج؟","شو صلاحيات لجنة الدراسات العليا في الكلية؟")
